{
  "findings": [
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "Parents can view and delete browsing history, search history, location activity, and app usage for child accounts via the privacy dashboard.",
      "stance": "mitigation",
      "quote": "For Microsoft products and services that require parental consent, parents can view and delete certain data about their child, such as browsing history, search history, location activity, and app usage by signing into the parent’s privacy dashboard."
    },
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "Child data can be deleted through the close your account form after signing into the child's account.",
      "stance": "mitigation",
      "quote": "To delete all your child’s personal information, request deletion of the child’s account using the close your account form. Sign in to your child’s account, ensure the correct account is shown, and follow the instructions."
    },
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "Microsoft may store and process personal data in the United States and other jurisdictions where Microsoft operates facilities.",
      "stance": "neutral",
      "quote": "Microsoft may store and process your personal data in your region, the United States, and any other jurisdiction where Microsoft or its affiliates, subsidiaries, or service providers operate facilities."
    },
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "Microsoft complies with the EU-U.S. Data Privacy Framework and similar frameworks for international data transfers.",
      "stance": "neutral",
      "quote": "Microsoft Corporation complies with the EU-U.S. Data Privacy Framework (EU-U.S. DPF), the UK Extension to the EU-U.S. DPF, and the Swiss-U.S. Data Privacy Framework (Swiss-U.S. DPF) as set forth by the U.S. Department of Commerce."
    }
  ]
}
